<?php
declare(strict_types=1);require_once __DIR__.'/report-dates.php';require_once __DIR__.'/workbook-events.php';
function staff_timeline(array $sessions,array $activity,array $range):array {
 $zone=new DateTimeZone('Asia/Ho_Chi_Minh');$from=new DateTimeImmutable($range['from'],$zone);$to=(new DateTimeImmutable($range['to'],$zone))->modify('+1 day');$days=(int)$from->diff($to)->days;if($days<1||$days>31)throw new RuntimeException('Chọn tối đa 31 ngày.',400);$users=[];$ensure=static function($username)use(&$users,$from,$to){if(isset($users[$username]))return;$daily=[];for($d=$from;$d<$to;$d=$d->modify('+1 day'))$daily[$d->format('Y-m-d')]=['active'=>array_fill(0,288,0),'online'=>array_fill(0,288,0)];$users[$username]=['username'=>$username,'daily'=>$daily,'minutes'=>[]];};
 foreach($sessions as $s){$name=$s['username'];$ensure($name);$start=max($from->getTimestamp(),(int)$s['started']);$end=min($to->getTimestamp(),(int)($s['ended']??$s['seen']));for($t=intdiv($start,300)*300;$t<$end;$t+=300){$d=(new DateTimeImmutable('@'.$t))->setTimezone($zone);$day=$d->format('Y-m-d');$bin=(int)$d->format('G')*12+intdiv((int)$d->format('i'),5);if(isset($users[$name]['daily'][$day]))$users[$name]['daily'][$day]['online'][$bin]=1;}}
 foreach($activity as $a){$t=(int)$a['at'];if($t<$from->getTimestamp()||$t>=$to->getTimestamp())continue;$name=$a['username'];$ensure($name);$minute=intdiv($t,60);if(isset($users[$name]['minutes'][$minute]))continue;$users[$name]['minutes'][$minute]=true;$d=(new DateTimeImmutable('@'.$t))->setTimezone($zone);$users[$name]['daily'][$d->format('Y-m-d')]['active'][(int)$d->format('G')*12+intdiv((int)$d->format('i'),5)]++;}
 foreach($users as &$u){$active=array_fill(0,288,0);$online=$active;foreach($u['daily'] as $d){foreach($d['active'] as $b=>$v)$active[$b]+=$v;foreach($d['online'] as $b=>$v)$online[$b]+=$v;}$u['activeMinutes']=count($u['minutes']);unset($u['minutes']);$u['active']=$active;$u['online']=$online;$u['days']=$days;}unset($u);return array_values($users);
}
function staff_insights(array $input):array {
 people_require_owner();$range=report_range($input);$zone=new DateTimeZone('Asia/Ho_Chi_Minh');$start=(new DateTimeImmutable($range['from'],$zone))->getTimestamp();$end=(new DateTimeImmutable($range['to'],$zone))->modify('+1 day')->getTimestamp();if(($end-$start)>31*86400)throw new RuntimeException('Chọn tối đa 31 ngày.',400);$db=team_db();people_schema($db);$q=$db->prepare('SELECT username,started,seen,ended FROM work_sessions WHERE user_id>0 AND started<? AND COALESCE(ended,seen)>=?');$q->execute([$end,$start]);$sessions=$q->fetchAll();$q=$db->prepare('SELECT s.username,a.at FROM work_activity a JOIN work_sessions s ON s.id=a.session_id WHERE s.user_id>0 AND a.at>=? AND a.at<? ORDER BY a.at');$q->execute([$start,$end]);$activity=$q->fetchAll();$timeline=staff_timeline($sessions,$activity,$range);$names=[];foreach(team_users() as $u)$names[$u['username']]=$u['name']?:$u['username'];foreach($timeline as &$u)$u['name']=$names[$u['username']]??$u['username'];unset($u);
 $orders=admin_db();wb_events_schema($orders);$from=gmdate('c',$start);$to=gmdate('c',$end);$q=$orders->prepare('SELECT actor,COUNT(*) AS total,SUM(CASE WHEN valid=0 THEN 1 ELSE 0 END) AS count FROM workbook_product_checks WHERE created_at>=? AND created_at<? GROUP BY actor HAVING count>0 ORDER BY count DESC');$q->execute([$from,$to]);$issues=$q->fetchAll();$q=$orders->prepare('SELECT actor,sheet_name,address,value,errors,created_at FROM workbook_input_issues WHERE created_at>=? AND created_at<? ORDER BY id DESC LIMIT 200');$q->execute([$from,$to]);return ['range'=>$range,'timeline'=>$timeline,'issues'=>$issues,'issueDetails'=>$q->fetchAll(),'names'=>$names];
}
